import{_ as t,o as s,c as i,a0 as a}from"./chunks/framework.DVUHX04-.js";const u=JSON.parse('{"title":"Home","description":"","frontmatter":{"layout":"home","title":"Home","hero":{"name":"pi-extensions","text":"A pi package that bundles pi extensions","tagline":"Semantic code search, quota recovery, and cross-device config sync for the pi coding agent.","actions":[{"theme":"brand","text":"codegraph","link":"/extensions/codegraph/"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1789791105000}'),o={name:"index.md"};function n(d,e,r,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[a('<h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Install from the git repository into user settings (default):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/SeriousJul/pi-extensions</span></span></code></pre></div><p>Or into project settings, shared with the team:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/SeriousJul/pi-extensions</span></span></code></pre></div><p>pi clones the repository and runs <code>npm install</code> for you, which also applies the codegraph postinstall patch. Update with <code>pi update --extensions</code>. Remove with <code>pi remove https://github.com/SeriousJul/pi-extensions</code>, list with <code>pi list</code>.</p><h2 id="extensions" tabindex="-1">Extensions <a class="header-anchor" href="#extensions" aria-label="Permalink to &quot;Extensions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Extension</th><th>What it does</th></tr></thead><tbody><tr><td><a href="/pi-extensions/extensions/codegraph/">codegraph</a></td><td>Semantic code index for the agent: four tools plus <code>/codegraph</code>, one index per git worktree, dependency sources via <code>projectRoot</code>.</td></tr><tr><td><a href="/pi-extensions/extensions/tools.html">tools</a></td><td>The <code>/tools</code> command to enable and disable tools per session.</td></tr><tr><td><a href="/pi-extensions/extensions/context-cap.html">context-cap</a></td><td><code>--context-window &lt;tokens&gt;</code> caps the session&#39;s context window so compaction fires early.</td></tr><tr><td><a href="/pi-extensions/extensions/initial-context.html">initial-context</a></td><td><code>/ctx</code> shows the token breakdown of the agent&#39;s initial context, with per-tool usage.</td></tr><tr><td><a href="/pi-extensions/extensions/model-router.html">model-router</a></td><td>Recovers a session from a provider usage-limit halt (switch to a fallback or wait for the reset, then resume).</td></tr><tr><td><a href="/pi-extensions/extensions/llama-refresh.html">llama-refresh</a></td><td>Self-heals the context window of a session that resolved a local llama.cpp model while it was asleep.</td></tr><tr><td><a href="/pi-extensions/extensions/quota.html">quota</a></td><td>Monitors the OpenAI ChatGPT plan quota: a footer line with the used windows, and a <code>/quota</code> detail view.</td></tr><tr><td><a href="/pi-extensions/extensions/sync/">sync</a></td><td>Cross-device pi config sync: <code>/sync</code> plus the <code>pi-sync</code> CLI, three-way merge, v1 backend a secret GitHub Gist.</td></tr><tr><td><a href="/pi-extensions/extensions/usage.html">usage</a></td><td>The <code>pi-usage</code> CLI and the usage report: token and cost usage across all pi sessions.</td></tr><tr><td><a href="/pi-extensions/extensions/compress.html">compress</a></td><td>Replaces finished turns in outgoing requests with one short standing-in message; the session file stays intact.</td></tr><tr><td><a href="/pi-extensions/extensions/edit-assist.html">edit-assist</a></td><td>Corrects and diagnoses built-in edit calls: leading-whitespace drift corrected before execution, a Nearest region diff on no-match, occurrence lines on ambiguous matches, one targeted hint on malformed calls; the stock error text is always kept.</td></tr></tbody></table>',8)])])}const x=t(o,[["render",n]]);export{u as __pageData,x as default};
